import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>


namespace cute_matmul_detail {

using namespace cute;
constexpr int TileM = 64;
constexpr int TileN = 32;
constexpr int TileK = 32;
constexpr int Threads = 128;
constexpr int SmemBStride = TileN + 1;

__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    extern __shared__ float smem[];

    float* As_ptr = smem;
    float* Bs_ptr = As_ptr + TileM * TileK;

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(As_ptr),
        make_layout(
            make_shape(Int<TileM>{}, Int<TileK>{}),
            make_stride(Int<TileK>{}, Int<1>{})));

    auto sB = make_tensor(
        make_smem_ptr(Bs_ptr),
        make_layout(
            make_shape(Int<TileK>{}, Int<TileN>{}),
             make_stride(Int<SmemBStride>{}, Int<1>{})));

    int tid = threadIdx.x;
    int block_m = blockIdx.y * TileM;
    int block_n = blockIdx.x * TileN;

    float accum[2][8];
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 8; ++j) {
            accum[i][j] = 0.0f;
        }
    }

    for (int k_tile = 0; k_tile < K; k_tile += TileK) {
        const bool vecA =
            (K % 4 == 0) &&
            (block_m + TileM <= M) &&
            (k_tile + TileK <= K) &&
            ((reinterpret_cast<unsigned long long>(A) & 0xFULL) == 0);
        if (vecA) {
            constexpr int AVecK = TileK / 4;
            for (int linear = tid; linear < TileM * AVecK; linear += Threads) {
                int r = linear / AVecK;
                int kv = linear - r * AVecK;
                const float4* src = reinterpret_cast<const float4*>(
                    A + (block_m + r) * K + k_tile + kv * 4);
                float4* dst = reinterpret_cast<float4*>(As_ptr + r * TileK + kv * 4);
                *dst = *src;
            }
        } else {
            for (int linear = tid; linear < TileM * TileK; linear += Threads) {
                int r = linear / TileK;
                int k = linear - r * TileK;
                int gr = block_m + r;
                int gk = k_tile + k;
                sA(r, k) = (gr < M && gk < K) ? gA(gr, gk) : 0.0f;
            }
        }
        const bool vecB =
            (N % 4 == 0) &&
            (k_tile + TileK <= K) &&
            (block_n + TileN <= N) &&
            ((reinterpret_cast<unsigned long long>(B) & 0xFULL) == 0);
        if (vecB) {
            constexpr int BVecN = TileN / 4;
            for (int linear = tid; linear < TileK * BVecN; linear += Threads) {
                int k = linear / BVecN;
                int cv = linear - k * BVecN;
                const float4* src = reinterpret_cast<const float4*>(
                    B + (k_tile + k) * N + block_n + cv * 4);
                 float4 v = *src;
                 Bs_ptr[k * SmemBStride + cv * 4 + 0] = v.x;
                 Bs_ptr[k * SmemBStride + cv * 4 + 1] = v.y;
                 Bs_ptr[k * SmemBStride + cv * 4 + 2] = v.z;
                 Bs_ptr[k * SmemBStride + cv * 4 + 3] = v.w;
            }
        } else {
            for (int linear = tid; linear < TileK * TileN; linear += Threads) {
                int k = linear / TileN;
                int c = linear - k * TileN;
                int gk = k_tile + k;
                int gc = block_n + c;
                sB(k, c) = (gk < K && gc < N) ? gB(gk, gc) : 0.0f;
            }
        }
        __syncthreads();

        int lane_id = tid & 31;
        int warp_id = tid >> 5;
     int row_base = warp_id * 16 + (lane_id / 4) * 2;
     int col_base = (lane_id % 4) * 8;
        #pragma unroll
        for (int k = 0; k < TileK; ++k) {
            #pragma unroll
            for (int i = 0; i < 2; ++i) {
                float a = sA(row_base + i, k);
                #pragma unroll
                for (int j = 0; j < 8; ++j) {
                    accum[i][j] += a * sB(k, col_base + j);
                }
            }
        }

        __syncthreads();
    }

    int lane_id = tid & 31;
    int warp_id = tid >> 5;
    int row_base = warp_id * 16 + (lane_id / 4) * 2;
    int col_base = (lane_id % 4) * 8;
    const bool vecC =
        (N % 4 == 0) &&
        (block_m + TileM <= M) &&
        (block_n + TileN <= N) &&
        ((reinterpret_cast<unsigned long long>(C) & 0xFULL) == 0);
    if (vecC) {
        #pragma unroll
        for (int i = 0; i < 2; ++i) {
            int row = block_m + row_base + i;
            float4 v0 = make_float4(
                accum[i][0], accum[i][1], accum[i][2], accum[i][3]);
            float4 v1 = make_float4(
                accum[i][4], accum[i][5], accum[i][6], accum[i][7]);
            float4* dst = reinterpret_cast<float4*>(C + row * N + block_n + col_base);
            dst[0] = v0;
            dst[1] = v1;
        }
    } else {
        #pragma unroll
        for (int i = 0; i < 2; ++i) {
            int row = block_m + row_base + i;
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                int col = block_n + col_base + j;
                if (row < M && col < N) {
                    gC(row, col) = accum[i][j];
                }
            }
        }
    }
}

} // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be 2-dimensional");
    TORCH_CHECK(B.dim() == 2, "B must be 2-dimensional");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.size(1) == B.size(0), "matmul dimension mismatch");

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();

    int M = static_cast<int>(A_contiguous.size(0));
    int K = static_cast<int>(A_contiguous.size(1));
    int N = static_cast<int>(B_contiguous.size(1));

    auto C = torch::empty({M, N}, A_contiguous.options());

    dim3 block(cute_matmul_detail::Threads);
    dim3 grid(
        (N + cute_matmul_detail::TileN - 1) / cute_matmul_detail::TileN,
        (M + cute_matmul_detail::TileM - 1) / cute_matmul_detail::TileM);

    constexpr size_t shared_bytes =
         (cute_matmul_detail::TileM * cute_matmul_detail::TileK +
          cute_matmul_detail::TileK * cute_matmul_detail::SmemBStride) * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matmul_detail::cute_matmul_kernel<<<grid, block, shared_bytes, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CuTE matmul kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_tall_skinny_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

