#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <mma.h>
#include <cute/tensor.hpp>


namespace cute_matmul_detail {
using namespace cute;
using namespace nvcuda;
constexpr int TileM = 64;
constexpr int TileN = 32;
constexpr int TileK = 32;
constexpr int Threads = 256;
constexpr int WarpM = 16;
constexpr int WarpN = 16;
constexpr int WarpsN = TileN / WarpN;
constexpr int NumWarps = (TileM / WarpM) * WarpsN;
__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    extern __shared__ float smem[];
    float* As_ptr = smem;
    float* Bs_ptr = As_ptr + TileM * TileK;
    float* Cs_ptr = Bs_ptr + TileK * TileN;
    int tid = threadIdx.x;
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    int block_m = blockIdx.y * TileM;
    int block_n = blockIdx.x * TileN;
    wmma::fragment<wmma::accumulator, WarpM, WarpN, 16, float> accum;
    wmma::fill_fragment(accum, 0.0f);
    for (int k_tile = 0; k_tile < K; k_tile += TileK) {
        for (int linear = tid; linear < TileM * TileK; linear += Threads) {
            int r = linear / TileK;
            int k = linear % TileK;
            int gr = block_m + r;
            int gk = k_tile + k;
            As_ptr[r * TileK + k] =
                (gr < M && gk < K) ? A[gr * K + gk] : 0.0f;
        }
        for (int linear = tid; linear < TileK * TileN; linear += Threads) {
            int k = linear / TileN;
            int n = linear % TileN;
            int gk = k_tile + k;
            int gn = block_n + n;
            Bs_ptr[k * TileN + n] =
                (gk < K && gn < N) ? B[gk * N + gn] : 0.0f;
        }
        __syncthreads();
        int warp_m = warp_id / WarpsN;
        int warp_n = warp_id % WarpsN;
        int smem_a_offset = warp_m * WarpM * TileK;
        int smem_b_offset = warp_n * WarpN;
        for (int kk = 0; kk < TileK; kk += 16) {
            wmma::fragment<wmma::matrix_a, WarpM, WarpN, 16, float, wmma::row_major> a_frag;
            wmma::fragment<wmma::matrix_b, WarpM, WarpN, 16, float, wmma::row_major> b_frag;
            wmma::load_matrix_sync(
                a_frag, As_ptr + smem_a_offset + kk, TileK);
            wmma::load_matrix_sync(
                b_frag, Bs_ptr + kk * TileN + smem_b_offset, TileN);
            wmma::mma_sync(a_frag, b_frag, accum, accum);
        }
        __syncthreads();
    }
    int warp_m = warp_id / WarpsN;
    int warp_n = warp_id % WarpsN;
    float* warp_c = Cs_ptr + warp_id * WarpM * WarpN;
    wmma::store_matrix_sync(warp_c, accum, WarpN, wmma::mem_row_major);
    __syncthreads();
    int tile_row = warp_m * WarpM;
    int tile_col = warp_n * WarpN;
    for (int linear = tid; linear < WarpM * WarpN; linear += Threads) {
        int local_row = linear / WarpN;
        int local_col = linear % WarpN;
        int row = block_m + tile_row + local_row;
        int col = block_n + tile_col + local_col;
        if (row < M && col < N) {
            C[row * N + col] = warp_c[local_row * WarpN + local_col];
        }
    }
}
} // namespace cute_matmul_detail
