    int N = static_cast<int>(B_contiguous.size(1));
    auto C = torch::empty({M, N}, A_contiguous.options());
    dim3 block(cute_matmul_detail::Threads);
    dim3 grid(
        (N + cute_matmul_detail::TileN - 1) / cute_matmul_detail::TileN,
        (M + cute_matmul_detail::TileM - 1) / cute_matmul_detail::TileM);
    constexpr size_t shared_bytes =
        (cute_matmul_detail::TileM * cute_matmul_detail::TileK +
         cute_matmul_detail::TileK * cute_matmul_detail::TileN +
         cute_matmul_detail::NumWarps * cute_matmul_detail::WarpM *
             cute_matmul_detail::WarpN) * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
